const input = $input.first().json;

const required = ['alert_type', 'source_workflow_id', 'source_workflow_name', 'subject'];
for (const field of required) {
  if (!input[field]) {
    throw new Error('Missing required field: ' + field);
  }
}

const bodyContent = (input.subject || '') + (input.body_html || '');
let hash = 5381;
for (let i = 0; i < bodyContent.length; i++) {
  hash = ((hash << 5) + hash) + bodyContent.charCodeAt(i);
  hash = hash & hash;
}
const body_hash = Math.abs(hash).toString(16).padStart(8, '0');

const now = new Date();
const berlinTime = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
const berlinHour = berlinTime.getHours();
const berlinDay = berlinTime.getDay();
const is_weekend = berlinDay === 0 || berlinDay === 6;
const isNight = berlinHour < 7 || berlinHour >= 22;

let time_context = 'business_hours';
if (isNight && is_weekend) time_context = 'night_weekend';
else if (isNight) time_context = 'night';
else if (is_weekend) time_context = 'weekend';

const CRITICAL_WORKFLOWS = [
  'CS4jhqo9tdd0cPe4', 'TLLSwYTcIRgtinVg', '6otS4c8KAuQKSdxz',
  '2fRdyqdyVDMWwH4O', 'IdFouG1kp8Uo23W5'
];
const is_critical_workflow = CRITICAL_WORKFLOWS.includes(input.source_workflow_id);
const force_send = input.severity_hint === 'critical' ||
  (input.metadata && input.metadata.force_send === true);

const body_preview = (input.body_html || '')
  .replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 500);

return {
  json: {
    alert_type: input.alert_type,
    severity_hint: input.severity_hint || 'unknown',
    source_workflow_id: input.source_workflow_id,
    source_workflow_name: input.source_workflow_name,
    subject: input.subject,
    body_html: input.body_html || '',
    body_preview,
    body_hash,
    metadata: input.metadata || {},
    time_context,
    is_weekend,
    is_critical_workflow,
    force_send
  }
};

const alert = $input.first().json;
return {
  json: {
    ...alert,
    ai_decision: 'email',
    ai_confidence: 1.0,
    ai_reasoning: 'Force send: Critical severity oder Force-Flag gesetzt',
    ai_tokens_used: 0,
    fallback_used: false
  }
};

const alert = $('Build Context').first().json;
const AUDIT_MODE = true;

let aiOutput = '';
let fallback_used = false;
let tokens_used = 0;

try {
  const response = $input.first().json;
  aiOutput = response.text || response.output || response.response || '';
  if (response.tokenUsage) {
    tokens_used = response.tokenUsage.totalTokens || 0;
  }
} catch (e) {
  fallback_used = true;
}

let decision = 'email';
let confidence = 0.5;
let reasoning = 'Fallback: AI-Antwort konnte nicht verarbeitet werden';

if (!fallback_used && aiOutput) {
  try {
    const jsonMatch = aiOutput.match(/\{[\s\S]*?\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      decision = parsed.decision || 'email';
      confidence = parseFloat(parsed.confidence) || 0.5;
      reasoning = parsed.reasoning || 'Keine Begruendung';
    } else {
      fallback_used = true;
    }
  } catch (e) {
    fallback_used = true;
    reasoning = 'Fallback: Parse-Fehler - ' + e.message;
  }
}

if (['escalate', 'email_and_telegram', 'telegram'].includes(decision)) {
  reasoning += ' [Escalate -> Email (kein Telegram)]';
  decision = 'email';
}

if (alert.severity_hint === 'critical' && decision === 'suppress') {
  decision = 'email';
  reasoning += ' [Override: Critical]';
}

if (alert.is_critical_workflow && decision === 'suppress') {
  decision = 'email';
  reasoning += ' [Override: Geschaeftskritisch]';
}

if (decision === 'suppress' && confidence < 0.6) {
  decision = 'email';
  reasoning += ' [Override: Confidence < 0.6]';
}

const original_decision = decision;
if (AUDIT_MODE && decision === 'suppress') {
  decision = 'email';
  reasoning += ' [AUDIT MODE: suppress -> email]';
}

return {
  json: {
    ...alert,
    ai_decision: decision,
    ai_decision_original: original_decision,
    ai_confidence: confidence,
    ai_reasoning: reasoning,
    ai_tokens_used: tokens_used,
    fallback_used
  }
};
